    s := Server{"localhost", 8080}
    fmt.Printf("Server on %s:%d\n", s.Host, s.Port)
}

package main
import "fmt"
type Worker interface { Work() string }
type Bot struct{}
func (b Bot) Work() string { return "Bot processing jobs" }
func main() {
    var w Worker = Bot{}
    fmt.Println(w.Work())
}

fn main() {
    let mut count = 0;
    count += 1;
    println!("Rust counter: {}", count);
}

fn get_length(s: &String) -> usize { s.len() }
fn main() {
    let text = String::from("EduMind");
    println!("Length: {}", get_length(&text));
}

enum Status { Ok(i32), Err }
fn main() {
    match Status::Ok(200) {
        Status::Ok(code) => println!("Success code: {}", code),
        Status::Err => println!("Failed"),
    }
}
